package com.ruoyi.system.service.impl;
import java.util.List; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import com.ruoyi.common.exception.ServiceException; import com.ruoyi.system.domain.shop.MallMemberAddress; import com.ruoyi.system.domain.shop.app.AppMemberAddressRequest; import com.ruoyi.system.mapper.shop.MallMemberMapper; import com.ruoyi.system.service.IAppMemberAddressService;
@Service public class AppMemberAddressServiceImpl implements IAppMemberAddressService { @Autowired private MallMemberMapper memberMapper; public List<MallMemberAddress> list(Long memberId){return memberMapper.selectAddressesByMemberId(memberId);} @Transactional(rollbackFor=Exception.class) public MallMemberAddress add(Long memberId,AppMemberAddressRequest request){MallMemberAddress address=copy(memberId,null,request);if(Boolean.TRUE.equals(request.getIsDefault())||list(memberId).isEmpty()){memberMapper.clearDefaultAddress(memberId);address.setIsDefault("1");}else address.setIsDefault("0");memberMapper.insertAddress(address);return address;} @Transactional(rollbackFor=Exception.class) public MallMemberAddress update(Long memberId,Long addressId,AppMemberAddressRequest request){MallMemberAddress existing=require(memberId,addressId);MallMemberAddress address=copy(memberId,addressId,request);address.setIsDefault(Boolean.TRUE.equals(request.getIsDefault())?"1":existing.getIsDefault());if("1".equals(address.getIsDefault()))memberMapper.clearDefaultAddress(memberId);if(memberMapper.updateAddressByMember(address)==0)throw new ServiceException("收货地址不存在");return require(memberId,addressId);} public int delete(Long memberId,Long addressId){if(memberMapper.deleteAddressByMember(addressId,memberId)==0)throw new ServiceException("收货地址不存在");return 1;} @Transactional(rollbackFor=Exception.class) public int setDefault(Long memberId,Long addressId){require(memberId,addressId);memberMapper.clearDefaultAddress(memberId);if(memberMapper.setDefaultAddress(addressId,memberId)==0)throw new ServiceException("收货地址不存在");return 1;} private MallMemberAddress require(Long memberId,Long addressId){MallMemberAddress address=memberMapper.selectAddressByMember(addressId,memberId);if(address==null)throw new ServiceException("收货地址不存在");return address;} private MallMemberAddress copy(Long memberId,Long addressId,AppMemberAddressRequest r){MallMemberAddress a=new MallMemberAddress();a.setMemberId(memberId);a.setAddressId(addressId);a.setReceiverName(r.getReceiverName().trim());a.setReceiverPhone(r.getReceiverPhone());a.setProvinceCode(r.getProvinceCode());a.setProvinceName(r.getProvinceName());a.setCityCode(r.getCityCode());a.setCityName(r.getCityName());a.setDistrictCode(r.getDistrictCode());a.setDistrictName(r.getDistrictName());a.setDetailAddress(r.getDetailAddress().trim());return a;} }
